    // Whether a mob of this spec eats the given item.
    inline bool eats(const MobSpec& mob, std::string_view item) {
        for (int i = 0; i < mob.food_count; ++i) {
            if (kFoodItems[mob.food_begin + i] == item) {
                return true;
            }
        }
        return false;
    }

    inline const MobSpec* find_mob(std::string_view id) {
        for (const auto& mob : kMobs) {
            if (mob.id == id) {
                return &mob;
            }
        }
        return nullptr;
    }

    inline const MobSpec* find_mob_by_name(const std::string& name) {
        const std::string key =
            name.find(':') == std::string::npos ? "minecraft:" + name : name;
        return find_mob(key);
    }

